import {
  Box,
  Typography,
  Button,
  TextField,
  CircularProgress,
  Link,
} from "@mui/material";
import BaseCard from "../../../components/Cards/Card";
import { useTheme } from "@mui/material/styles";
import useMediaQuery from "@mui/material/useMediaQuery";
import { useFormik } from "formik";
import { toast } from "react-hot-toast";
import { useNavigate } from "react-router-dom";
import { useState } from "react";
import { setOtpData } from "../../../Redux/Slices/AuthSlice";
import { useDispatch } from "react-redux";

const BASE_URL = process.env.REACT_APP_API_BASE_URL;

const ForgetPassword = () => {
  const theme = useTheme();

  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const dispatch = useDispatch();

  const validate = (values) => {
    const errors = {};
    if (!values.email) {
      errors.email = "Email is required";
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)) {
      errors.email = "Email is invalid";
    }
    return errors;
  };

  const handleSubmit = async (values) => {
    setLoading(true);
    values.email = values.email.toLowerCase();
    try {
      const response = await fetch(`${BASE_URL}/auth/forgot-password`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: values.email }),
      });

      const result = await response.json();

      if (!response.ok || result.error) {
        throw new Error(result.message || "Failed to send OTP");
      }

      toast.success(result.message || "OTP sent successfully!");

      dispatch(
        setOtpData({
          email: values.email,
          otp: result.data.otp,
        }),
      );

      setTimeout(() => {
        navigate(`/verification?email=${values.email}`);
      }, 1500);
    } catch (error) {
      console.error("🚨 Forget Password error:", error);
      toast.error(error.message || "Failed to send OTP");
    } finally {
      setLoading(false);
    }
  };

  const formik = useFormik({
    initialValues: { email: "" },
    validate,
    onSubmit: handleSubmit,
  });

  return (
    <Box sx={{ width: "100%", display: "flex", justifyContent: "center" }}>
      <BaseCard
        maxWidth={isMobile ? "100%" : 400}
        sx={{
          width: isMobile ? "100%" : 400,
          p: 4,
          backgroundColor: "rgba(0, 0, 0, 0.7)", // Semi-transparent black
          backdropFilter: "blur(16px)", // Glassmorphism effect
          border: "1px solid #4CC66E", // Premium green full border
          borderRadius: "16px",
          boxShadow: "0 8px 32px 0 rgba(0, 0, 0, 0.8)",
        }}
      >
        <form onSubmit={formik.handleSubmit}>
          <Box sx={{ display: "flex", flexDirection: "column", gap: 3 }}>
            {/* Logo Section */}
            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 1, mb: 1 }}>
              <img src="/favicon.svg" style={{ width: 100, height: 100, objectFit: "contain" }} alt="Logo" />
              
            </Box>

            <Box sx={{ textAlign: 'center' }}>
              <Typography variant="h5" sx={{ color: "#FFFFFF", mb: 0.5 }}>
                Forget Password
              </Typography>
              <Typography variant="body2" sx={{ color: "text.secondary" }}>
                Enter your email address to receive a verification code.
              </Typography>
            </Box>

            <Box sx={{ display: "flex", flexDirection: "column", gap: 1 }}>
              <Typography variant="body2" sx={{ color: "#FFFFFF" }}>
                Email
              </Typography>
              <TextField
                fullWidth
                name="email"
                placeholder="john@gmail.com"
                value={formik.values.email}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={formik.submitCount > 0 && Boolean(formik.errors.email)}
                helperText={formik.submitCount > 0 && formik.errors.email}
              />
            </Box>

            <Button
              variant="contained"
              type="submit"
              disabled={loading}
              startIcon={
                loading && <CircularProgress size={20} color="inherit" />
              }
            >
              Submit
            </Button>

            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                mt: 1,
                gap: 0.5,
              }}
            >
              <Typography variant="body2" sx={{ color: "text.secondary" }}>
                Remember your password?
              </Typography>
              <Link
                component="button"
                variant="body2"
                onClick={() => navigate("/")}
                sx={{
                  color: "primary.main",
                  textDecoration: "none",
                  fontWeight: 600,
                  cursor: "pointer",
                  "&:hover": { textDecoration: "underline" },
                }}
              >
                Sign In
              </Link>
            </Box>
          </Box>
        </form>
      </BaseCard>
    </Box>
  );
};

export default ForgetPassword;
